var root = $input.first() ? ($input.first().json || {}) : {};
var body = (root && root.body !== undefined) ? root.body : root;
var defs = [];
if (Array.isArray(body)) { defs = body; }
else if (body && Array.isArray(body.credentials)) { defs = body.credentials; }
else if (body && body.name && body.type) { defs = [body]; }
var out = [];
for (var i = 0; i < defs.length; i++) {
  var d = defs[i] || {};
  var name = (d.name !== undefined && d.name !== null) ? String(d.name).trim() : '';
  var type = (d.type !== undefined && d.type !== null) ? String(d.type).trim() : '';
  var data = (d.data && typeof d.data === 'object' && !Array.isArray(d.data)) ? d.data : null;
  var valid = !!(name && type && data);
  out.push({ json: { name: name, type: type, data: data || {}, valid: valid, reason: valid ? '' : 'missing name, type, or data object' } });
}
if (out.length === 0) { return [{ json: { _empty: true } }]; }
return out;

var items = $input.all().map(function (i) { return i.json || {}; });
var results = [];
var created = 0, failed = 0;
for (var i = 0; i < items.length; i++) {
  var r = items[i];
  if (r._empty || (!r.name && !r.type && !r.status)) continue;
  results.push({ name: r.name || '', type: r.type || '', status: r.status || 'failed', id_or_error: r.id_or_error || r.reason || '' });
  if (r.status === 'created') created++; else failed++;
}
if (results.length === 0) {
  return [{ json: { total: 0, created: 0, failed: 0, error: 'no valid credential definitions' } }];
}
return [{ json: { total: results.length, created: created, failed: failed, results: results } }];

var j = $input.item.json || {};
var valid = !!j.valid;
var body = valid ? { name: j.name, type: j.type, data: j.data } : {};
return { json: { name: j.name || '', type: j.type || '', valid: valid, reason: j.reason || '', createBody: body } };

var prep = {};
try { prep = $('Prep Create').item.json || {}; } catch (e) { prep = {}; }
var resp = $input.item.json || {};
var name = prep.name || '';
var type = prep.type || '';
if (!prep.valid) {
  return { json: { name: name, type: type, status: 'failed', id_or_error: prep.reason || 'invalid definition' } };
}
var id = '';
if (resp && typeof resp.id === 'string') id = resp.id;
else if (resp && typeof resp.id === 'number') id = String(resp.id);
if (id) {
  return { json: { name: name, type: type, status: 'created', id_or_error: id } };
}
var err = '';
try { if (resp && resp.message) err = String(resp.message); } catch (e) {}
if (!err) { try { err = JSON.stringify(resp).slice(0, 300); } catch (e) { err = 'unknown error'; } }
return { json: { name: name, type: type, status: 'failed', id_or_error: err || 'create failed' } };
